INSERT INTO t_articles (id, doi, title, authors, article_year, status, abstract, keywords, upload_timestamp, last_status_change) VALUES (1, 'https://doi.org/10.1101/2024.12.15.628567', 'Complete Test Article: Effects of environmental factors on species adaptation', 'Jane Smith, John Doe, Maria Garcia', '2024', 'Recommended', 'This study examines the effects of various environmental factors on species adaptation mechanisms. Our results demonstrate significant correlations between environmental variability and adaptive responses.', 'evolution, adaptation, environmental factors', '2026-01-07 11:51:59.646288', '2026-01-07 11:51:59.646288');
INSERT INTO t_recommendations (id, article_id, recommender_id, recommendation_doi, recommendation_state, recommendation_title, recommendation_comments, no_conflict_of_interest, validation_timestamp, recommendation_timestamp, last_change, reply) VALUES (2, 1, 1, '10.24072/pci.neuro.100217', 'Recommended', 'Recommendation: An important contribution to our understanding of species adaptation', 'This is a comprehensive and well-executed study on species adaptation. The methodology is sound and the results are well-presented. I recommend this manuscript for publication.', true, '2026-01-07 11:52:43.730961', '2026-01-07 11:52:43.730961', '2026-01-07 11:52:43.730961', 'Reply: yeas please.');
INSERT INTO t_reviews (id, recommendation_id, reviewer_id, review_state, review, no_conflict_of_interest, anonymously, last_change) VALUES (1, 2, 1, 'Review completed', 'This manuscript presents a **thorough** investigation of environmental factors on <i>species</i> adaptation. The experimental design is robust and the statistical analysis is appropriate. The results are clearly presented and well-discussed. I have only minor suggestions for improvement. Overall, this is excellent work that deserves publication.', true, false, '2026-01-07 11:52:53.148807');
INSERT INTO t_reviews (id, recommendation_id, reviewer_id, review_state, review, no_conflict_of_interest, anonymously, last_change) VALUES (2, 2, 1, 'Review completed', 'The authors have conducted a comprehensive study on species adaptation mechanisms. The methodology is sound and the conclusions are well-supported by the data. This work makes a valuable contribution to the field and I recommend it for publication.', true, false, '2026-01-07 11:53:04.58744');
INSERT INTO t_recommendations (id, article_id, recommender_id, recommendation_doi, recommendation_state, recommendation_title, recommendation_comments, no_conflict_of_interest, validation_timestamp, recommendation_timestamp, last_change) VALUES (3, 1, 1, '10.24072/pci.neuro.100217', 'Recommended', 'Another recommendation title', 'An important way to reduce animal use in research is to design adequately statistically powered experiments. Critically, one needs to select an experimental task that is not too easy to solve by chance, and an appropriate number of repetitions each animal is required to perform. Optimising such parameters allows selecting the lowest number of animals required to get a robust result. While there are some estimation tools available for optimising these parameters, behavioural paradigms in neuroscience are highly diverse, and not all available tools are easily amenable for the design of all types of experiments. One such example is spatial memory paradigms such as mazes where the animal must remember the correct path to a reward (e.g. plus-maze, or radial arm maze). Desachy et al (Desachy et al., 2025) report a new freely available online tool for this type of cognitive tasks.', true, '2026-01-07 11:52:43.730961', '2026-01-07 11:52:43.730961', '2026-01-07 11:52:43.730961');